// Conversation transcript with stable scroll anchoring: the list follows new
// content only while the reader is at the bottom; scrolling up to reread
// pins the viewport until they return to the bottom. Tool activity cards
// render beneath the assistant message that called them; the change log and
// the manufacturing history render after the conversation item they follow,
// in the order they happened.

import { Fragment, ReactNode, useEffect, useLayoutEffect, useRef, useState } from 'react';
import {
  AttachmentInfo,
  BuildInfo,
  ChangeInfo,
  WorkInfo,
  RestorePointInfo,
  ExportedCopyInfo,
  PhysicalPrintInfo,
  PrinterBlock,
  ToolActivityInfo,
} from '../bridge/protocol';
import { Message } from '../state/store';
import { AttachmentChip } from './AttachmentChip';
import { ChangeRows } from './ChangeRows';
import { FileNotesCard } from './FileNotesCard';
import { MarkdownMessage } from './MarkdownMessage';
import { ToolActivityCard } from './ToolActivityCard';
import { collapseWork, WorkCard } from './WorkCard';
import { ManufacturingHistoryCard, ManufacturingHistoryEntry } from './ManufacturingHistoryCard';
import { PrinterBlockView } from './PrinterPanel';
import { splitChoices, withoutPartialChoices } from '../replyChoices';

interface Props {
  messages: Message[];
  attachments: AttachmentInfo[];
  streamingMessageId: string | null;
  toolActivities: ToolActivityInfo[];
  builds: BuildInfo[];
  exportedCopies: ExportedCopyInfo[];
  physicalPrints: PhysicalPrintInfo[];
  changes: ChangeInfo[]; // already filtered to this conversation
  work?: WorkInfo[]; // already filtered to this conversation
  onWorkCancel?: (id: string) => void;
  restorePoints?: RestorePointInfo[];
  onRevert?: (versionId: string) => void;
  onRetry: (messageId: string) => void;
  onToolCancel: (actionId: string) => void;
  // Sends a reply chip's text as the person's message.
  onSend: (text: string) => void;
  replyDisabled?: boolean;
  readOnly?: boolean;
  endNotice?: ReactNode;
  onDiscussFailure?: (text: string) => void;
  // The printer panel's own cards, each anchored after the message that drew
  // it, the way history entries are. Absent everywhere else, and its
  // presence is what makes this the printer panel's thread.
  printerBlocks?: PrinterBlock[];
  // Undo on an added printer's receipt, by block id.
  onUndoAdd?: (blockId: string) => void;
  // Install on the notice that Bambu's network plug-in is missing.
  onInstallPlugin?: () => void;
  // A surface's own card for one of its tool calls, in place of the generic
  // one; undefined keeps the generic card.
  renderActivity?: (activity: ToolActivityInfo) => ReactNode | undefined;
  // Set up on the card of a file's notes, when the Agent could not speak.
  onSetUpAgent?: () => void;
  // Whether any of the thread is scrolled out under what is pinned above it,
  // reported as it changes and as false when the thread goes away.
  onScrolledChange?: (scrolled: boolean) => void;
}

// What follows one conversation item: history cards and runs of changes, in
// seq order. Consecutive changes form one block, which draws as one group.
type TimelineBlock =
  | { kind: 'history'; seq: number; entry: ManufacturingHistoryEntry }
  | { kind: 'changes'; seq: number; changes: ChangeInfo[] }
  | { kind: 'work'; seq: number; work: WorkInfo[] };

function timeline(history: ManufacturingHistoryEntry[], changes: ChangeInfo[], work: WorkInfo[] = []): TimelineBlock[] {
  const items = [
    ...history.map((entry) => ({ seq: entry.seq, history: entry, change: undefined, work: undefined })),
    ...changes.map((change) => ({ seq: change.seq, history: undefined, change, work: undefined })),
    ...work.map((entry) => ({ seq: entry.seq, history: undefined, change: undefined, work: entry })),
  ].sort((a, b) => a.seq - b.seq);
  const blocks: TimelineBlock[] = [];
  for (const item of items) {
    const previous = blocks[blocks.length - 1];
    if (item.change && previous?.kind === 'changes') previous.changes.push(item.change);
    else if (item.change) blocks.push({ kind: 'changes', seq: item.seq, changes: [item.change] });
    else if (item.work && previous?.kind === 'work') previous.work.push(item.work);
    else if (item.work) blocks.push({ kind: 'work', seq: item.seq, work: [item.work] });
    else blocks.push({ kind: 'history', seq: item.seq, entry: item.history! });
  }
  return blocks;
}

function TimelineBlocks({ blocks, restorePoints, onRevert, onDiscussFailure, discussDisabled, onWorkCancel, readOnly }: {
  blocks: TimelineBlock[];
  onWorkCancel?: (id: string) => void;
  readOnly?: boolean;
  restorePoints: RestorePointInfo[];
  onRevert?: (versionId: string) => void;
  onDiscussFailure: (print: PhysicalPrintInfo) => void;
  discussDisabled: boolean;
}) {
  return (
    <>
      {blocks.map((block) =>
        block.kind === 'history' ? (
          <ManufacturingHistoryCard key={`${block.entry.kind}-${block.entry.record.id}`} entry={block.entry}
            onDiscussFailure={onDiscussFailure} discussDisabled={discussDisabled} />
        ) : block.kind === 'work' ? (
          collapseWork(block.work).map(({ work, times }) => (
            <WorkCard key={work.id} work={work} times={times} onCancel={onWorkCancel ?? (() => {})} readOnly={readOnly || !onWorkCancel} />
          ))
        ) : (
          <ChangeRows key={`changes-${block.seq}`} changes={block.changes} restorePoints={restorePoints} onRevert={onRevert} />
        ),
      )}
    </>
  );
}

export function MessageList({
  messages,
  attachments,
  streamingMessageId,
  toolActivities,
  builds,
  exportedCopies,
  physicalPrints,
  changes,
  work = [],
  onWorkCancel,
  restorePoints = [],
  onRevert,
  onRetry,
  onToolCancel,
  onSend,
  replyDisabled = false,
  readOnly = false,
  endNotice,
  onDiscussFailure,
  printerBlocks,
  onUndoAdd,
  onInstallPlugin,
  renderActivity,
  onSetUpAgent,
  onScrolledChange,
}: Props) {
  const attachmentsById = new Map(attachments.map((attachment) => [attachment.id, attachment]));
  const listRef = useRef<HTMLDivElement>(null);
  const [followBottom, setFollowBottom] = useState(true);

  const handleScroll = () => {
    const list = listRef.current;
    if (!list) return;
    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
    setFollowBottom(distanceFromBottom < 24);
    onScrolledChange?.(list.scrollTop > 0);
  };

  useEffect(() => () => onScrolledChange?.(false), [onScrolledChange]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (list && followBottom) list.scrollTop = list.scrollHeight;
  }, [messages, toolActivities, builds, exportedCopies, physicalPrints, changes, printerBlocks, followBottom]);
  const printerPanel = printerBlocks !== undefined;

  // A copy made immediately from a build is one G-code event in the thread.
  // Keep later copies separate so an intervening edit never moves in history.
  const pairedCopies = new Set<string>();
  const history: ManufacturingHistoryEntry[] = [
    ...builds.map((record) => {
      const copy = exportedCopies.find((item) => item.buildId === record.id && item.seq === record.seq + 1);
      if (copy) pairedCopies.add(copy.id);
      return { kind: 'build' as const, seq: record.seq, afterMessageId: record.afterMessageId, record, copy };
    }),
    ...exportedCopies.filter((record) => !pairedCopies.has(record.id))
      .map((record) => ({ kind: 'copy' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
    ...physicalPrints.map((record) => ({ kind: 'print' as const, seq: record.seq, afterMessageId: record.afterMessageId, record })),
  ];
  const activitiesOf = (messageId: string) => toolActivities.filter((activity) => activity.correlationId === messageId);
  // A change follows a message or one of its tool activities; both place it
  // after that message's group.
  const messageOfItem = new Map<string, string>();
  for (const message of messages) {
    messageOfItem.set(message.id, message.id);
    for (const activity of activitiesOf(message.id)) messageOfItem.set(activity.actionId, message.id);
  }
  const changesAfter = (messageId: string) => changes.filter((change) => messageOfItem.get(change.afterId) === messageId);
  const leadingChanges = changes.filter((change) => !messageOfItem.has(change.afterId));
  // Work keeps the place it started at: after the item that was last then,
  // so a message that arrived later reads below it.
  const workAfter = (messageId: string) => work.filter((entry) => messageOfItem.get(entry.afterId) === messageId);
  const leadingWork = work.filter((entry) => !messageOfItem.has(entry.afterId));
  const historyAfter = (messageId: string) => history.filter((entry) => entry.afterMessageId === messageId);
  const printerBlockViews = (messageId: string) =>
    (printerBlocks ?? [])
      .filter((block) => block.afterMessageId === messageId)
      .sort((a, b) => a.seq - b.seq)
      .map((block) => <PrinterBlockView key={block.id} block={block} onUndoAdd={onUndoAdd} onInstallPlugin={onInstallPlugin} />);
  const leadingHistory = history.filter(
    (entry) => entry.afterMessageId === '' || !messages.some((message) => message.id === entry.afterMessageId),
  );
  const discussFailure = (print: PhysicalPrintInfo) =>
    (onDiscussFailure ?? onSend)(`Help me understand why this print failed: ${print.failure || 'The print stopped unexpectedly.'}`);

  return (
    <div className="message-list" role="log" aria-label="Agent conversation"
      ref={listRef} onScroll={handleScroll}>
      <TimelineBlocks blocks={timeline(leadingHistory, leadingChanges, leadingWork)} onWorkCancel={onWorkCancel} readOnly={readOnly} restorePoints={readOnly ? [] : restorePoints} onRevert={readOnly ? undefined : onRevert}
        onDiscussFailure={discussFailure} discussDisabled={readOnly || streamingMessageId !== null} />
      {messages.length === 0 && (
        <div className="notice">
          <h2>Ask the Agent about your print</h2>
          <p>
            The Agent can describe the open project, the plates and objects on them, the current selection, and the
            printer setup — or duplicate the selected object.
          </p>
        </div>
      )}
      {messages.map((message) => {
        // A file's load report is for the model. The person sees it only
        // when the Agent could not speak about it, as the card of what
        // OrcaSlicer said.
        if (message.role === 'note' && message.fileReport)
          return message.fileReportCard ? (
            <div key={message.id} className="message-group">
              <FileNotesCard report={message.fileReport} onSetUpAgent={onSetUpAgent} />
            </div>
          ) : null;
        if (message.role === 'note')
          return (
            <div key={message.id} className="message-group">
              <div className="message note" role="status">
                {/* The colour a change landed on, drawn and never named: the
                    app holds a colour as a value, not a word. */}
                {message.swatch && <span className="note-swatch" style={{ background: message.swatch }} aria-hidden="true" />}
                {message.text}
              </div>
              {printerBlockViews(message.id)}
            </div>
          );
        // In the printer panel a photo is how the person says which printer
        // it is, or shows what changed: it draws inline, above any words as
        // their caption, rather than as a named file chip below them.
        const attached = (message.attachments ?? []).map((id) => attachmentsById.get(id)).filter((a): a is AttachmentInfo => !!a);
        const photos = printerPanel ? attached.filter((a) => a.kind === 'image' && a.previewDataUrl) : [];
        const otherAttachments = attached.filter((a) => !photos.includes(a));
        // The model sometimes calls a printer tool with no words yet: its
        // actual reply lands in a later, separate message once it sees the
        // tool's result. A bare, empty bubble either mid-stream or once it
        // settles reads as a rendering bug, not a pause -- name the work
        // while streaming, and draw nothing once it settles still empty. A
        // failed or stopped turn always still renders, so its error and
        // Retry stay reachable.
        const emptyPrinterTurn =
          printerPanel &&
          message.role === 'assistant' &&
          !message.text &&
          photos.length === 0 &&
          otherAttachments.length === 0 &&
          message.state !== 'stopped' &&
          !(message.state === 'failed' && message.error);
        const workingOnCard = emptyPrinterTurn && message.id === streamingMessageId;
        // Only the newest finished reply offers its choices; any later
        // message, the person's own included, answers them.
        const streaming = message.id === streamingMessageId;
        const reply =
          message.role !== 'assistant'
            ? { body: message.text, choices: [] }
            : streaming
              ? { body: withoutPartialChoices(message.text), choices: [] }
              : splitChoices(message.text);
        const choices =
          message.state === 'complete' && message.id === messages[messages.length - 1].id ? reply.choices : [];
        const bubble = workingOnCard ? (
          // Chat/System Line: a quiet line of status while the model works.
          <div className="message assistant">
            <div className="printer-activity" role="status">
              <span className="jp-icon jp-icon-rotate-cw" aria-hidden="true" />
              Working on it…
            </div>
          </div>
        ) : emptyPrinterTurn ? null : (
          <div className={`message ${message.role}`}>
            <div className="message-content">
              {photos.length > 0 && (
                <div className="message-photos">
                  {photos.map((attachment) => (
                    <img
                      key={attachment.id}
                      className="message-photo"
                      src={attachment.previewDataUrl}
                      alt={attachment.name || 'Photo'}
                    />
                  ))}
                </div>
              )}
              {reply.body &&
                (message.role === 'assistant' ? (
                  <MarkdownMessage streaming={streaming}>{reply.body}</MarkdownMessage>
                ) : (
                  <span>{reply.body}</span>
                ))}
              {choices.length > 0 && (
                <div className="reply-chips">
                  {choices.map((choice) => (
                    <button key={choice} type="button" className="reply-chip" disabled={replyDisabled}
                      onClick={() => onSend(choice)}>
                      {choice}
                    </button>
                  ))}
                </div>
              )}
              {otherAttachments.length > 0 && (
                <div className="message-attachments">
                  {otherAttachments.map((attachment) => (
                    <AttachmentChip key={attachment.id} attachment={attachment} />
                  ))}
                </div>
              )}
              {message.state === 'failed' && message.error && (
                <div className="message-failure">
                  <div className="error">{message.error.message}</div>
                  {message.error.retryable && !readOnly && (
                    <button className="primary" onClick={() => onRetry(message.id)}>Retry</button>
                  )}
                </div>
              )}
              {message.state === 'stopped' && <div className="meta">Stopped</div>}
            </div>
          </div>
        );
        // The message group is one thread item: the turn and the tool cards
        // it called, 8 apart. What follows it -- change runs and history
        // entries -- are thread items of their own.
        return (
          <Fragment key={message.id}>
            <div className="message-group">
              {bubble}
              {activitiesOf(message.id).map((activity) => {
                const own = renderActivity?.(activity);
                if (own !== undefined) return <Fragment key={activity.actionId}>{own}</Fragment>;
                return <ToolActivityCard key={activity.actionId} activity={activity}
                  onCancel={onToolCancel} readOnly={readOnly} />;
              })}
            </div>
            {printerBlockViews(message.id)}
            <TimelineBlocks blocks={timeline(historyAfter(message.id), changesAfter(message.id), workAfter(message.id))} onWorkCancel={onWorkCancel} readOnly={readOnly} restorePoints={readOnly ? [] : restorePoints} onRevert={readOnly ? undefined : onRevert}
              onDiscussFailure={discussFailure} discussDisabled={readOnly || streamingMessageId !== null} />
          </Fragment>
        );
      })}
      {endNotice}
    </div>
  );
}
#################### ToolActivityCard
// One native tool action, rendered from the authoritative activity record
// the host pushes. The native coordinator owns the state machine.

import { ReactNode } from 'react';
import { ToolActivityInfo, ToolStateName } from '../bridge/protocol';
import { Progress } from './Progress';

interface Props {
  activity: ToolActivityInfo;
  onCancel: (actionId: string) => void;
  readOnly?: boolean;
}

const stateLabels: Record<ToolStateName, string> = {
  running: 'Running…',
  succeeded: 'Done',
  failed: 'The action failed.',
  cancelled: 'Cancelled — nothing was changed',
};

// Which glyph a state's line leads with. Colour is never the only signal: the
// line always has its icon and its words.
const stateIcons: Record<ToolStateName, string> = {
  running: 'running',
  succeeded: 'done',
  failed: 'failed',
  cancelled: 'cancelled',
};

// The one status line every state of a tool card has.
export function ToolStatus({ state, children }: { state: ToolStateName; children: ReactNode }) {
  return (
    <div className={`tool-state ${stateIcons[state]}`}>
      <span className={`tool-status-icon ${stateIcons[state]}`} aria-hidden="true" />
      <span className="tool-state-text">{children}</span>
    </div>
  );
}

export function ToolActivityCard({ activity, onCancel, readOnly = false }: Props) {
  const { state } = activity;
  const stale = state === 'failed' && activity.error?.code === 'stale_revision';
  const measured = activity.progress.total > 0;
  const percent = measured ? Math.round((100 * activity.progress.current) / activity.progress.total) : 0;
  const message =
    state === 'running' && measured
      ? `Running… · ${percent}%`
      : state === 'failed'
        ? stale
          ? 'The project changed before this could run. Ask the Agent again.'
          : activity.error?.message ?? stateLabels.failed
        : stateLabels[state];

  return (
    <div className={`tool-card state-${state}`} data-testid={`tool-${activity.actionId}`}
      title={`${activity.tool} · ${activity.server}`}>
      <div className="tool-title">{activity.title}</div>
      <ToolStatus state={state}>{message}</ToolStatus>

      {state === 'running' && (
        <>
          <Progress label={`${activity.title} progress`}
            value={state === 'running' && measured ? activity.progress.current : undefined}
            max={state === 'running' && measured ? activity.progress.total : undefined} />
          <div className="tool-actions">
            <button disabled={readOnly} onClick={() => onCancel(activity.actionId)}>Cancel</button>
          </div>
        </>
      )}
    </div>
  );
}
#################### WorkCard
// Work the application ran outside the chat: a slice, an arrange, an export.
// While it runs the card carries its progress and, where the work can be
// stopped, a Cancel button; when it ends the same card says how. It is drawn
// from the tool card's own pieces, so it reads as the same kind of thing.

import type { ToolStateName, WorkInfo, WorkStateName } from '../bridge/protocol';
import { Progress } from './Progress';
import { ToolStatus } from './ToolActivityCard';

interface Props {
  work: WorkInfo;
  // How many consecutive runs this card stands for; see `collapseWork`.
  times?: number;
  onCancel: (id: string) => void;
  readOnly?: boolean;
}

// The glyph each ending leads with. An interrupted run is shown as a failure
// would be: it did not finish.
const icons: Record<WorkStateName, ToolStateName> = {
  running: 'running',
  done: 'succeeded',
  cancelled: 'cancelled',
  failed: 'failed',
  interrupted: 'failed',
};

export function workStatus(work: WorkInfo): string {
  const total = work.progress?.total ?? 0;
  switch (work.state) {
    case 'running': {
      const words = work.detail || 'Running…';
      return total > 0 ? `${words} · ${Math.round((100 * (work.progress?.current ?? 0)) / total)}%` : words;
    }
    case 'done':
      return 'Done';
    case 'cancelled':
      return 'Cancelled';
    case 'failed':
      return work.detail || 'It did not finish.';
    case 'interrupted':
      return 'Interrupted when the project was closed';
  }
}

// Consecutive runs that ended the same way and have the same title read as one
// card with a count, so slicing ten times is not ten cards. Nothing is merged
// in what is saved, and a run that is still going always stands alone.
export function collapseWork(entries: WorkInfo[]): { work: WorkInfo; times: number }[] {
  const cards: { work: WorkInfo; times: number }[] = [];
  for (const work of entries) {
    const last = cards[cards.length - 1];
    if (last && work.state !== 'running' && last.work.state === work.state && last.work.kind === work.kind &&
        last.work.title === work.title && last.work.detail === work.detail)
      cards[cards.length - 1] = { work, times: last.times + 1 };
    else cards.push({ work, times: 1 });
  }
  return cards;
}

export function WorkCard({ work, times = 1, onCancel, readOnly = false }: Props) {
  const running = work.state === 'running';
  const total = work.progress?.total ?? 0;
  return (
    <div className={`tool-card state-${icons[work.state]}`} data-testid={`work-${work.id}`}>
      <div className="tool-title">
        {work.title}
        {times > 1 && <span className="work-times"> · {times} times</span>}
      </div>
      <ToolStatus state={icons[work.state]}>{workStatus(work)}</ToolStatus>
      {running && (
        <>
          <Progress label={`${work.title} progress`} value={total > 0 ? work.progress?.current : undefined}
            max={total > 0 ? total : undefined} />
          {work.cancellable && (
            <div className="tool-actions">
              <button disabled={readOnly} onClick={() => onCancel(work.id)}>Cancel</button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

