import json, re, sys
from pathlib import Path
src = Path(sys.argv[1]) / "project"; out = Path(sys.argv[1]) / "harness"; out.mkdir(exist_ok=True)
t = json.loads((src / "tokens.json").read_text())
themes = [x["id"] for x in t["color"]["themes"]]
def v(tok, th): return tok["value"] if isinstance(tok["value"], str) else tok["value"].get(th, tok["value"][themes[0]])
css = []
for f in t["type"]["fonts"]:
    css.append(f"@font-face{{font-family:'{f['family']}';src:url('../project/{f['file']}');font-weight:{f['weight']};font-style:{f['style']}}}")
for i, th in enumerate(themes):
    sel = ':root,[data-theme="%s"]' % th if i == 0 else '[data-theme="%s"]' % th
    css.append(sel + "{" + "".join(f"--{k['name']}:{v(k, th)};" for fam in ("color", "shadow") for k in t[fam]["tokens"]) + "}")
css.append(":root{" + "".join(f"--{k['name']}:{k['value']};" for fam in ("spacing", "radius", "component") for k in t[fam]["tokens"])
           + "".join(f"--font-{k}:{s};" for k, s in t["type"]["families"].items()) + "}")
for g in t["type"]["groups"]:
    for s in g["styles"]:
        css.append(f".{s['name']}{{font-family:var(--font-{g['family']});font-size:{s['fontSize']};line-height:{s['lineHeight']};font-weight:{s['fontWeight']}}}")
(out / "tokens.css").write_text("\n".join(css))
head = '''<link rel="stylesheet" href="tokens.css"><link rel="stylesheet" href="../project/components/bundle.css">
<script src="https://unpkg.com/react@18.3.1/umd/react.production.min.js"></script>
<script src="https://unpkg.com/react-dom@18.3.1/umd/react-dom.production.min.js"></script>
<script src="../project/components/bundle.js"></script>'''
frames = {th: [] for th in themes}
for p in sorted((src / "components").glob("*/preview.html")):
    html = p.read_text()
    h = int(re.search(r"height=(\d+)", html).group(1))
    for th in themes:
        name = f"{p.parent.name}-{th}.html"
        (out / name).write_text(html.replace("<html lang=\"en\">", f'<html lang="en" data-theme="{th}">').replace("<head>", "<head>" + head, 1))
        w = 960 if p.parent.name == "Cover" else 700
        frames[th].append(f'<div style="{"grid-column:1/-1" if w == 960 else ""}"><p style="margin:2px 0">{p.parent.name}</p><iframe src="{name}" width="{w}" height="{h}" style="border:1px solid #bbb;display:block"></iframe></div>')
for th in themes:
    (out / f"index-{th}.html").write_text("<body style='font:11px sans-serif;margin:8px;display:grid;grid-template-columns:702px 702px;gap:6px 12px;align-items:start'>" + "\n".join(frames[th]))
print(sum(len(v) for v in frames.values()), "frames")
